export const FIXTURE_QUESTIONS: Question[] = RAW.map((q) => QuestionSchema.parse(q));

export function questionsByConcept(questions: Question[] = FIXTURE_QUESTIONS): Map<string, Question[]> {
  const out = new Map<string, Question[]>();
  for (const q of questions) {
    const list = out.get(q.conceptId) ?? [];
    list.push(q);
    out.set(q.conceptId, list);
  }
  return out;
}
